package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// stripDangerous removes known dangerous keywords but allows normal search
func stripDangerous(input string) string {
	// Remove null bytes and control characters
	cleaned := strings.Map(func(r rune) rune {
		if r < 32 && r != 9 && r != 10 && r != 13 {
			return -1
		}
		return r
	}, input)
	return cleaned
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	term := r.URL.Query().Get("term")
	if len(term) == 0 {
		http.Error(w, "Missing search term", 400)
		return
	}

	if len(term) > 200 {
		term = term[:200]
	}

	term = stripDangerous(term)

	// Build search query - using ILIKE for case-insensitive search
	// The term is wrapped in wildcards for partial matching
	query := fmt.Sprintf(
		"SELECT id, title, description, price FROM products WHERE title ILIKE '%%%s%%' OR description ILIKE '%%%s%%' ORDER BY price ASC LIMIT 50",
		term, term,
	)

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Search error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var title, description string
		var price float64
		if err := rows.Scan(&id, &title, &description, &price); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		line := fmt.Sprintf(`  {"id":%d,"title":"%s","description":"%s","price":%.2f}`,
			id, strings.ReplaceAll(title, `"`, `\"`), strings.ReplaceAll(description, `"`, `\"`), price)
		w.Write([]byte(line))
	}
	w.Write([]byte("\n]"))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
